    "question": "If an anther of a diploid plant contains 4 microsporangia, each with 50 pollen mother cells, and each ovule contains 1 megaspore mother cell: if all pollen grains fertilize ovules of another plant with 100% efficiency, how many seeds can be formed, and how many female meiotic divisions are required?",
