    "explanation": "1. CONCEPT:\nMeiotic vs mitotic division counts in megagametogenesis.\n\n2. STEP-BY-STEP SOLUTION:\nTo form 120 functional megaspores, 120 MMCs undergo 1 meiotic division each = 120 meiotic divisions. Each functional megaspore undergoes 3 successive free-nuclear mitotic divisions (1 -> 2 -> 4 -> 8 nuclei) to organize the mature embryo sac. Total mitotic division cycles = 120 x 3 = 360.\n\n3. FINAL ANSWER:\nOption B: 120 meiotic divisions and 360 mitotic divisions\n\n4. WHY OTHER OPTIONS ARE WRONG:\nMitosis is not 8 cycles; 3 successive cycles produce 8 nuclei (2^3 = 8).",
