    "explanation": "1. CONCEPT:\nQuantitative microsporogenesis and megasporogenesis.\n\n2. STEP-BY-STEP SOLUTION:\nEach PMC undergoes meiosis to produce 4 functional pollen grains. To obtain 500 pollen grains, 500/4 = 125 PMCs are required. Each MMC produces 4 megaspores, but 3 degenerate, leaving only 1 functional megaspore per MMC. Thus, 500 MMCs are required. Total = 125 PMCs and 500 MMCs.\n\n3. FINAL ANSWER:\nOption A: 125 PMCs and 500 MMCs\n\n4. WHY OTHER OPTIONS ARE WRONG:\n500 PMCs would produce 2000 pollen grains; 125 MMCs would produce only 125 seeds because 3 megaspores degenerate in each tetrad.",
