    "id": "sexual-repro-flowering-plants-mcq-400",
    "questionNumber": 400,
    "question": "A cross is performed between a tetraploid (4n = 48) female plant and a diploid (2n = 24) male plant. What will be the ploidy and chromosome number of the resulting embryo and endosperm, respectively?",
    "options": {
      "A": "Embryo: Triploid (3n = 36); Endosperm: Hexaploid (6n = 72)",
      "B": "Embryo: Tetraploid (4n = 48); Endosperm: Pentaploid (5n = 60)",
      "C": "Embryo: Triploid (3n = 36); Endosperm: Pentaploid (5n = 60)",
      "D": "Embryo: Tetraploid (4n = 48); Endosperm: Hexaploid (6n = 72)"
    },
    "optionsList": [
      "Embryo: Triploid (3n = 36); Endosperm: Hexaploid (6n = 72)",
      "Embryo: Tetraploid (4n = 48); Endosperm: Pentaploid (5n = 60)",
      "Embryo: Triploid (3n = 36); Endosperm: Pentaploid (5n = 60)",
      "Embryo: Tetraploid (4n = 48); Endosperm: Hexaploid (6n = 72)"
    ],
    "correctAnswer": "C",
    "correctOption": "C",
    "correctIndex": 2,
    "explanation": "1. CONCEPT:\nEmbryo and endosperm ploidy in non-standard genetic crosses.\n\n2. STEP-BY-STEP SOLUTION:\nFemale gamete has half the maternal ploidy, and central cell polar nuclei contribute two female gamete complements (2 x n_female). Male gamete contributes half the paternal ploidy (n_male). Embryo = n_female + n_male. Endosperm = (2 x n_female) + n_male.\n\n3. FINAL ANSWER:\nOption C: Embryo: Triploid (3n = 36); Endosperm: Pentaploid (5n = 60)\n\n4. WHY OTHER OPTIONS ARE WRONG:\nIncorrect options fail to account for the maternal contribution of two polar nuclei to the endosperm.",
    "solutionStructured": {
      "concept": "Embryo and endosperm ploidy in non-standard genetic crosses.",
      "stepByStep": "Female gamete has half the maternal ploidy, and central cell polar nuclei contribute two female gamete complements (2 x n_female). Male gamete contributes half the paternal ploidy (n_male). Embryo = n_female + n_male. Endosperm = (2 x n_female) + n_male.",
      "finalAnswer": "Option C: Embryo: Triploid (3n = 36); Endosperm: Pentaploid (5n = 60)",
      "whyOtherOptionsWrong": "Incorrect options fail to account for the maternal contribution of two polar nuclei to the endosperm."
    },
